import {existsSync, readFileSync} from "node:fs";
const read = path => JSON.parse(readFileSync(path));
const minutes = value => {
  const [hours, mins] = String(value).split(":").map(Number);
  return hours * 60 + mins;
};
const records = ["operations/cold-cycle.json", "operations/duty-2340.json"]
  .filter(existsSync)
  .map(read)
  .sort((left, right) => minutes(left.time) - minutes(right.time));
const log = records.at(-1);
const plan = read("shift-plan.json");
const night = read("night.json");
const limits = log.limitsKw ?? log.samples.map(s => (s.acMeterEndKwh - s.acMeterStartKwh) * 60 / s.minutes);
const actual = limits.map((k, i) => Math.min(k, plan.acKw[i]));
const eta = night.efficiency;
const departures = night.buses.map(bus => {
  let acKwh = 0;
  for (let slot = bus.fromSlot; slot < bus.untilSlot; slot += 1) {
    acKwh += actual[slot] * night.slotHours;
  }
  const endKwh = bus.startKwh + acKwh * eta;
  return {
    id: bus.id,
    acKwh,
    endKwh,
    requiredKwh: bus.requiredKwh,
    marginKwh: endKwh - bus.requiredKwh,
  };
});
const at85 = night.buses.map(bus => {
  let acKwh = 0;
  for (let slot = bus.fromSlot; slot < bus.untilSlot; slot += 1) {
    acKwh += actual[slot] * night.slotHours;
  }
  const endKwh = bus.startKwh + acKwh * night.lowerEfficiency;
  return {id: bus.id, endKwh, gapKwh: bus.requiredKwh - endKwh};
});
console.log(JSON.stringify({
  run: log.run,
  time: log.time,
  limits,
  actual,
  withinLimits: plan.acKw.every((k, i) => k <= limits[i] + 1e-9),
  departureKwh: departures.map(d => d.endKwh),
  marginKwh: departures.map(d => d.marginKwh),
  at85,
  dispatchAt85: plan.dispatchAt85,
}));
